local _, namespace = ...
namespace.releaseNotesByLocale = {["deDE"]={["sections"]={{["items"]={"Questfortschritt, der an Gruppenmitglieder ohne QuestTogether gesendet wird, beginnt jetzt mit [QT] statt mit [QuestTogether].","Ankündigungen beachten weiterhin das Limit für Chatnachrichten und erhalten vollständige Zeichen in jeder Sprache."},["title"]="Kompakte Gruppenankündigungen"}},["version"]="5.16.5",["welcome"]="Ein kürzeres Präfix hält Gruppenankündigungen kompakt."},["esES"]={["sections"]={{["items"]={"El progreso de las misiones publicado a los miembros del grupo sin QuestTogether ahora empieza con [QT] en lugar de [QuestTogether].","Los anuncios siguen respetando el límite de mensajes del chat y conservan caracteres completos en todos los idiomas."},["title"]="Anuncios de grupo compactos"}},["version"]="5.16.5",["welcome"]="Un prefijo más corto mantiene compactos los anuncios de grupo."},["esMX"]={["sections"]={{["items"]={"El progreso de misión publicado para miembros del grupo sin QuestTogether ahora empieza con [QT] en lugar de [QuestTogether].","Los anuncios siguen respetando el límite de mensajes del chat y conservan caracteres completos en todos los idiomas."},["title"]="Anuncios de grupo compactos"}},["version"]="5.16.5",["welcome"]="Un prefijo más corto mantiene compactos los anuncios del grupo."},["frFR"]={["sections"]={{["items"]={"La progression des quêtes publiée aux membres du groupe sans QuestTogether commence désormais par [QT] au lieu de [QuestTogether].","Les annonces respectent toujours la limite des messages de discussion et préservent les caractères complets dans toutes les langues."},["title"]="Annonces de groupe compactes"}},["version"]="5.16.5",["welcome"]="Un préfixe plus court rend les annonces de groupe plus compactes."},["itIT"]={["sections"]={{["items"]={"I progressi delle missioni inviati ai membri del gruppo senza QuestTogether ora iniziano con [QT] invece di [QuestTogether].","Gli annunci continuano a rispettare il limite dei messaggi della chat e preservano caratteri completi in ogni lingua."},["title"]="Annunci di gruppo compatti"}},["version"]="5.16.5",["welcome"]="Un prefisso più breve mantiene compatti gli annunci del gruppo."},["koKR"]={["sections"]={{["items"]={"이제 QuestTogether가 없는 파티원에게 게시되는 퀘스트 진행 상황은 [QuestTogether] 대신 [QT]로 시작합니다.","알림은 여전히 대화 메시지 제한을 준수하며 모든 언어에서 문자가 온전하게 유지됩니다."},["title"]="간결한 파티 알림"}},["version"]="5.16.5",["welcome"]="짧은 접두사는 파티 알림을 간결하게 유지합니다."},["ptBR"]={["sections"]={{["items"]={"O progresso da missão enviado aos membros do grupo sem QuestTogether agora começa com [QT] em vez de [QuestTogether].","Os anúncios ainda respeitam o limite de mensagens do chat e preservam caracteres completos em todos os idiomas."},["title"]="Anúncios compactos para o grupo"}},["version"]="5.16.5",["welcome"]="Um prefixo mais curto mantém os anúncios do grupo compactos."},["ruRU"]={["sections"]={{["items"]={"Прогресс задания, отправляемый членам группы без QuestTogether, теперь начинается с [QT] вместо [QuestTogether].","Объявления по-прежнему учитывают ограничение длины сообщения в чате и сохраняют целые символы на любом языке."},["title"]="Компактные объявления группе"}},["version"]="5.16.5",["welcome"]="Более короткий префикс делает объявления группе компактнее."},["zhCN"]={["sections"]={{["items"]={"发送给未安装 QuestTogether 的小队成员的任务进度现在以 [QT] 开头，而不是 [QuestTogether]。","通告仍会遵守聊天消息长度限制，并在各种语言中保留完整字符。"},["title"]="简洁小队通告"}},["version"]="5.16.5",["welcome"]="较短的前缀可让小队通告更简洁。"},["zhTW"]={["sections"]={{["items"]={"發送給沒有 QuestTogether 的隊伍成員的任務進度，現在會以 [QT] 開頭，而不是 [QuestTogether]。","公告仍會遵守聊天訊息長度限制，並在所有語言中保留完整字元。"},["title"]="精簡隊伍公告"}},["version"]="5.16.5",["welcome"]="較短的前綴可讓隊伍公告更精簡。"}}
